package typed

import (
	"errors"
	"fmt"
	"math/big"
	"sort"
	"strconv"
	"strings"
	"sync"

	profinet "github.com/otfabric/go-profinet"
)

// The validation tables are generated by gsdmlc from the GSDML reference
// schemas (zz_tables.go): every simple type, complex type, element
// declaration, content automaton and identity constraint of every schema
// version, deduplicated across versions. The functions in this file
// evaluate them; nothing here reads a schema.

// Flags of complexSpec.
const (
	cMixed uint8 = 1 << iota
	cAbstract
	cAnyType
	cSimpleContent
)

type complexSpec struct {
	name    string
	flags   uint8
	simple  int32 // simple content
	attrs   []attrSpec
	anyAttr int32 // wildcard, or -1
	// dfa is the content automaton; state 0 is the start. Empty for
	// empty content.
	dfa []dfaState
}

type dfaState struct {
	final bool
	trans []dfaTrans
}

// dfaTrans: an element (elem >= 0) or a wildcard (wild >= 0).
type dfaTrans struct {
	elem, wild, next int32
}

// Flags of attrSpec and elemSpec.
const (
	fRequired uint8 = 1 << iota
	fDefault
	fFixed
	fAbstract
	fGlobal
)

type attrSpec struct {
	ns, local  string
	simple     int32
	flags      uint8
	def, fixed string
}

type elemSpec struct {
	ns, local   string
	complex     int32
	simple      int32
	flags       uint8
	def, fixed  string
	substitutes []int32
	idcs        []int32
}

// Wildcard modes and processing.
const (
	wAny uint8 = iota
	wOther
	wList
)

const (
	pStrict uint8 = iota
	pLax
	pSkip
)

type wildcardSpec struct {
	mode    uint8
	target  string
	allowed []string
	process uint8
}

func (w *wildcardSpec) allows(ns string) bool {
	switch w.mode {
	case wAny:
		return true
	case wOther:
		return ns != w.target && ns != ""
	}
	for _, a := range w.allowed {
		if a == ns {
			return true
		}
	}
	return false
}

// Identity constraint kinds.
const (
	idcKey uint8 = iota
	idcUnique
	idcKeyref
)

type idcSpec struct {
	kind     uint8
	name     string
	refer    int32
	selector []xpath
	fields   [][]xpath
}

type xpath struct {
	descendant bool
	steps      []xstep
}

// Step kinds.
const (
	xSelf uint8 = iota
	xChild
	xAnyChild   // "*"
	xAnyChildNS // "p:*"
	xAttr
)

type xstep struct {
	kind      uint8
	ns, local string
}

type versionSpec struct {
	version string
	globals []int32 // global element declarations, by name
	attrs   []attrSpec

	once   sync.Once
	byName map[[2]string]int32
}

type schemaTables struct {
	simples   []simpleSpec
	patterns  []pattern
	complexes []complexSpec
	elements  []elemSpec
	wildcards []wildcardSpec
	idcs      []idcSpec
	versions  []versionSpec
}

func (v *versionSpec) global(sc *schemaTables, ns, local string) (int32, bool) {
	v.once.Do(func() {
		v.byName = make(map[[2]string]int32, len(v.globals))
		for _, g := range v.globals {
			e := &sc.elements[g]
			v.byName[[2]string{e.ns, e.local}] = g
		}
	})
	i, ok := v.byName[[2]string{ns, local}]
	return i, ok
}

// Issue is a schema-validity error.
type Issue struct {
	// Line of the element's start tag (0 for a document built in memory).
	Line int
	// Path of the element: its ancestors' and its local names.
	Path    string
	Message string
}

func (i Issue) String() string {
	if i.Line > 0 {
		return fmt.Sprintf("line %d: %s: %s", i.Line, i.Path, i.Message)
	}
	return i.Path + ": " + i.Message
}

// SchemaError is the error of Validate: the document is not valid against
// the schema of its version. It matches profinet.ErrMalformed.
type SchemaError struct {
	Version string
	Issues  []Issue
	// Truncated is set when more issues exist than MaxIssues.
	Truncated bool
}

// MaxIssues is the most issues a SchemaError lists.
const MaxIssues = 1000

func (e *SchemaError) Error() string {
	var b strings.Builder
	fmt.Fprintf(&b, "typed: not valid against GSDML V%s:", e.Version)
	for i, is := range e.Issues {
		if i == 10 {
			fmt.Fprintf(&b, " (and %d more)", len(e.Issues)-10)
			break
		}
		b.WriteString(" ")
		b.WriteString(is.String())
		if i < len(e.Issues)-1 && i < 9 {
			b.WriteString(";")
		}
	}
	return b.String()
}

// Is reports profinet.ErrMalformed.
func (e *SchemaError) Is(target error) bool { return target == profinet.ErrMalformed }

// ErrUnknownVersion is returned for a document whose schema version this
// package has no schema for.
var ErrUnknownVersion = errors.New("typed: unknown GSDML schema version")

type nodeInfo struct {
	complex, simple int32
	pre, end        int
}

type keyTable struct {
	node  *Node
	pre   int
	tuple map[string]bool
}

type validator struct {
	sc     *schemaTables
	ver    *versionSpec
	issues []Issue
	trunc  bool
	path   []string
	info   map[*Node]*nodeInfo
	tables map[int32][]keyTable
	count  int
}

func (v *validator) add(n *Node, format string, a ...any) {
	if len(v.issues) >= MaxIssues {
		v.trunc = true
		return
	}
	line := 0
	if n != nil {
		line = n.Line
	}
	v.issues = append(v.issues, Issue{Line: line, Path: "/" + strings.Join(v.path, "/"), Message: fmt.Sprintf(format, a...)})
}

func versionIndex(sc *schemaTables, version string) int {
	for i := range sc.versions {
		if sc.versions[i].version == version {
			return i
		}
	}
	return -1
}

// validateNode validates a document tree against the schema of version.
func validateNode(root *Node, version string) error {
	sc := tables
	vi := versionIndex(sc, version)
	if vi < 0 {
		return fmt.Errorf("%w: %q", ErrUnknownVersion, version)
	}
	v := &validator{sc: sc, ver: &sc.versions[vi], info: map[*Node]*nodeInfo{}, tables: map[int32][]keyTable{}}
	g, ok := v.ver.global(sc, root.Name.Space, root.Name.Local)
	v.path = append(v.path, root.Name.Local)
	if !ok {
		v.add(root, "no declaration for the root element {%s}%s", root.Name.Space, root.Name.Local)
	} else {
		v.element(root, g)
	}
	if len(v.issues) > 0 {
		return &SchemaError{Version: version, Issues: v.issues, Truncated: v.trunc}
	}
	return nil
}

func (v *validator) element(n *Node, ei int32) {
	sc := v.sc
	e := &sc.elements[ei]
	info := &nodeInfo{complex: -1, simple: -1, pre: v.count}
	v.count++
	v.info[n] = info
	if e.flags&fAbstract != 0 {
		v.add(n, "element %s is abstract", e.local)
	}
	for _, a := range n.Attrs {
		if a.Name.Space == nsXSI && (a.Name.Local == "type" || a.Name.Local == "nil") {
			v.add(n, "xsi:%s is not supported", a.Name.Local)
		}
	}
	if e.complex >= 0 {
		info.complex = e.complex
		v.complexContent(n, e.complex, e)
	} else {
		info.simple = e.simple
		for _, a := range n.Attrs {
			if a.Name.Space != nsXSI {
				v.add(n, "attribute %s is not allowed: element %s has a simple type", qualified(a.Name.Space, a.Name.Local), e.local)
			}
		}
		for _, c := range n.Children {
			if !c.IsText() {
				v.add(n, "element %s has a simple type and no element content, not %s", e.local, c.Name.Local)
				break
			}
		}
		v.simpleValue(n, e, e.simple)
	}
	info.end = v.count
	if len(e.idcs) > 0 {
		v.identity(n, e)
	}
}

// simpleValue checks an element's character data against a simple type,
// with the element's default and fixed value.
func (v *validator) simpleValue(n *Node, e *elemSpec, si int32) {
	text := n.CharData()
	if text == "" && e.flags&fDefault != 0 {
		text = e.def
	}
	if e.flags&fFixed != 0 {
		if text == "" {
			text = e.fixed
		} else if !v.sc.sameValue(si, text, e.fixed) {
			v.add(n, "the value %q is not the fixed value %q", text, e.fixed)
			return
		}
	}
	if err := v.sc.checkSimple(si, text, n); err != nil {
		v.add(n, "%v", err)
	}
}

func (sc *schemaTables) sameValue(si int32, a, b string) bool {
	t := &sc.simples[si]
	if t.variety != vAtomic {
		return collapse(a) == collapse(b)
	}
	return equalValue(t.builtin, normalizeWS(a, t.ws), normalizeWS(b, t.ws))
}

func (v *validator) complexContent(n *Node, ci int32, e *elemSpec) {
	sc := v.sc
	c := &sc.complexes[ci]
	if c.flags&cAbstract != 0 {
		v.add(n, "complex type %s is abstract", c.name)
	}
	// Attributes.
	seen := make([]bool, len(c.attrs))
	for _, a := range n.Attrs {
		if a.Name.Space == nsXSI {
			continue
		}
		found := -1
		for i := range c.attrs {
			if c.attrs[i].local == a.Name.Local && c.attrs[i].ns == a.Name.Space {
				found = i
				break
			}
		}
		if found >= 0 {
			seen[found] = true
			as := &c.attrs[found]
			if as.flags&fFixed != 0 && !sc.sameValue(as.simple, a.Value, as.fixed) {
				v.add(n, "attribute %s: the value %q is not the fixed value %q", a.Name.Local, a.Value, as.fixed)
				continue
			}
			if err := sc.checkSimple(as.simple, a.Value, n); err != nil {
				v.add(n, "attribute %s: %v", a.Name.Local, err)
			}
			continue
		}
		if c.anyAttr >= 0 {
			w := &sc.wildcards[c.anyAttr]
			if w.allows(a.Name.Space) {
				if w.process == pSkip {
					continue
				}
				if g := v.globalAttr(a.Name.Space, a.Name.Local); g != nil {
					if err := sc.checkSimple(g.simple, a.Value, n); err != nil {
						v.add(n, "attribute %s: %v", a.Name.Local, err)
					}
				} else if w.process == pStrict {
					v.add(n, "attribute %s: no declaration for the wildcard (strict)", a.Name.Local)
				}
				continue
			}
		}
		v.add(n, "attribute %s is not allowed", qualified(a.Name.Space, a.Name.Local))
	}
	for i := range c.attrs {
		if !seen[i] && c.attrs[i].flags&fRequired != 0 {
			v.add(n, "missing required attribute %s", c.attrs[i].local)
		}
	}
	// Content.
	if c.flags&cSimpleContent != 0 {
		for _, k := range n.Children {
			if !k.IsText() {
				v.add(n, "element %s has simple content, not element %s", n.Name.Local, k.Name.Local)
				return
			}
		}
		v.simpleValue(n, e, c.simple)
		return
	}
	mixed := c.flags&cMixed != 0
	if len(c.dfa) == 0 && !mixed {
		// empty content: no children at all, not even white space
		// (XML Schema 3.4.4, Element Locally Valid (Complex Type) 2.1)
		if len(n.Children) > 0 {
			if k := n.Children[0]; k.IsText() {
				v.add(n, "character content is not allowed: element %s has empty content", n.Name.Local)
			} else {
				v.add(n, "element %s has empty content, not element %s", n.Name.Local, k.Name.Local)
			}
		}
		return
	}
	if !mixed {
		for _, k := range n.Children {
			if k.IsText() && strings.TrimFunc(k.Text, isXMLSpace) != "" {
				v.add(n, "character content is not allowed in element %s", n.Name.Local)
				break
			}
		}
	}
	if len(c.dfa) == 0 {
		for _, k := range n.Children {
			if !k.IsText() {
				v.add(n, "element %s has empty content, not element %s", n.Name.Local, k.Name.Local)
				return
			}
		}
		return
	}
	state := int32(0)
	for _, k := range n.Children {
		if k.IsText() {
			continue
		}
		st := &c.dfa[state]
		matched := false
		for _, t := range st.trans {
			if t.elem >= 0 {
				if d, ok := sc.matchElement(t.elem, k); ok {
					v.path = append(v.path, k.Name.Local)
					v.element(k, d)
					v.path = v.path[:len(v.path)-1]
					state, matched = t.next, true
					break
				}
				continue
			}
			w := &sc.wildcards[t.wild]
			if !w.allows(k.Name.Space) {
				continue
			}
			v.path = append(v.path, k.Name.Local)
			switch w.process {
			case pStrict:
				if g, ok := v.ver.global(sc, k.Name.Space, k.Name.Local); ok {
					v.element(k, g)
				} else {
					v.add(k, "no declaration for element {%s}%s (strict wildcard)", k.Name.Space, k.Name.Local)
				}
			case pLax:
				if g, ok := v.ver.global(sc, k.Name.Space, k.Name.Local); ok {
					v.element(k, g)
				}
			}
			v.path = v.path[:len(v.path)-1]
			state, matched = t.next, true
			break
		}
		if !matched {
			v.add(k, "element %s is not expected here%s", qualified(k.Name.Space, k.Name.Local), v.expected(st))
			return
		}
	}
	if !c.dfa[state].final {
		v.add(n, "missing child element%s", v.expected(&c.dfa[state]))
	}
}

func qualified(ns, local string) string {
	if ns == "" {
		return local
	}
	return "{" + ns + "}" + local
}

func (v *validator) expected(st *dfaState) string {
	var names []string
	for _, t := range st.trans {
		if t.elem >= 0 {
			names = append(names, v.sc.elements[t.elem].local)
		} else {
			names = append(names, "(any element)")
		}
	}
	if len(names) == 0 {
		return " (no more elements allowed)"
	}
	return " (expected: " + strings.Join(names, ", ") + ")"
}

func (v *validator) globalAttr(ns, local string) *attrSpec {
	for i := range v.ver.attrs {
		if v.ver.attrs[i].ns == ns && v.ver.attrs[i].local == local {
			return &v.ver.attrs[i]
		}
	}
	return nil
}

// matchElement reports whether node k matches element declaration ei or
// a member of its substitution group, and returns the declaration that
// applies.
func (sc *schemaTables) matchElement(ei int32, k *Node) (int32, bool) {
	e := &sc.elements[ei]
	if e.local == k.Name.Local && e.ns == k.Name.Space {
		return ei, true
	}
	for _, s := range e.substitutes {
		se := &sc.elements[s]
		if se.local == k.Name.Local && se.ns == k.Name.Space {
			return s, true
		}
	}
	return 0, false
}

// selectNodes evaluates identity-constraint paths from n.
func selectNodes(n *Node, paths []xpath) []*Node {
	var out []*Node
	seen := map[*Node]bool{}
	for _, p := range paths {
		start := []*Node{n}
		if p.descendant {
			start = descendantsOrSelf(n)
		}
		cur := start
		for _, st := range p.steps {
			if st.kind == xAttr {
				break
			}
			var next []*Node
			for _, c := range cur {
				if st.kind == xSelf {
					next = append(next, c)
					continue
				}
				for _, k := range c.Children {
					if k.IsText() {
						continue
					}
					switch st.kind {
					case xChild:
						if k.Name.Local == st.local && k.Name.Space == st.ns {
							next = append(next, k)
						}
					case xAnyChild:
						next = append(next, k)
					case xAnyChildNS:
						if k.Name.Space == st.ns {
							next = append(next, k)
						}
					}
				}
			}
			cur = next
		}
		for _, c := range cur {
			if !seen[c] {
				seen[c] = true
				out = append(out, c)
			}
		}
	}
	return out
}

func descendantsOrSelf(n *Node) []*Node {
	out := []*Node{n}
	for i := 0; i < len(out); i++ {
		for _, k := range out[i].Children {
			if !k.IsText() {
				out = append(out, k)
			}
		}
	}
	return out
}

// fieldValue evaluates a field on a selected node: the value in its
// value space, prefixed by its primitive kind; ok is false when the field
// selects nothing; multi is set when it selects more than one node.
func (v *validator) fieldValue(t *Node, paths []xpath) (val string, ok, multi bool) {
	count := 0
	for _, p := range paths {
		last := p.steps[len(p.steps)-1]
		if last.kind == xAttr {
			holders := selectNodes(t, []xpath{{descendant: p.descendant, steps: p.steps[:len(p.steps)-1]}})
			if len(p.steps) == 1 && !p.descendant {
				holders = []*Node{t}
			}
			for _, h := range holders {
				for _, a := range h.Attrs {
					if a.Name.Local == last.local && a.Name.Space == last.ns {
						count++
						val = v.canonicalAttr(h, a.Name.Space, a.Name.Local, a.Value)
					}
				}
				if count == 0 {
					// the attribute's default applies (XML Schema 3.11.4)
					if as := v.attrSpecOf(h, last.ns, last.local); as != nil && as.flags&(fDefault|fFixed) != 0 {
						d := as.def
						if as.flags&fFixed != 0 {
							d = as.fixed
						}
						count++
						val = v.canonical(as.simple, d)
					}
				}
			}
			continue
		}
		for _, s := range selectNodes(t, []xpath{p}) {
			count++
			info := v.info[s]
			si := int32(-1)
			if info != nil {
				si = info.simple
				if info.complex >= 0 && v.sc.complexes[info.complex].flags&cSimpleContent != 0 {
					si = v.sc.complexes[info.complex].simple
				}
			}
			val = v.canonical(si, s.CharData())
		}
	}
	return val, count > 0, count > 1
}

func (v *validator) attrSpecOf(h *Node, ns, local string) *attrSpec {
	info := v.info[h]
	if info == nil || info.complex < 0 {
		return nil
	}
	c := &v.sc.complexes[info.complex]
	for i := range c.attrs {
		if c.attrs[i].local == local && c.attrs[i].ns == ns {
			return &c.attrs[i]
		}
	}
	return nil
}

func (v *validator) canonicalAttr(h *Node, ns, local, value string) string {
	if as := v.attrSpecOf(h, ns, local); as != nil {
		return v.canonical(as.simple, value)
	}
	return "?" + value
}

// canonical maps a value to its value space for identity comparison:
// values of different primitive types never compare equal.
func (v *validator) canonical(si int32, raw string) string {
	if si < 0 {
		return "?" + raw
	}
	t := &v.sc.simples[si]
	if t.variety != vAtomic {
		return "s" + collapse(raw)
	}
	s := normalizeWS(raw, t.ws)
	switch {
	case t.builtin.numeric():
		if r, ok := new(big.Rat).SetString(trimPlus(s)); ok {
			return "d" + r.RatString()
		}
	case t.builtin.floating():
		if f, err := parseXSDFloat(s); err == nil {
			return "f" + strconv.FormatFloat(f, 'g', -1, 64)
		}
	case t.builtin == bBoolean:
		return "b" + strconv.FormatBool(boolValue(s))
	}
	return "s" + s
}

func (v *validator) identity(n *Node, e *elemSpec) {
	sc := v.sc
	// keys and uniques first, so that a keyref on the same element sees them
	order := make([]int32, 0, len(e.idcs))
	for _, c := range e.idcs {
		if sc.idcs[c].kind != idcKeyref {
			order = append(order, c)
		}
	}
	for _, c := range e.idcs {
		if sc.idcs[c].kind == idcKeyref {
			order = append(order, c)
		}
	}
	info := v.info[n]
	for _, ci := range order {
		c := &sc.idcs[ci]
		targets := selectNodes(n, c.selector)
		tuples := map[string]bool{}
		for _, t := range targets {
			if v.info[t] == nil {
				// not assessed: it follows content that did not match,
				// which is reported; its values have no type to compare
				continue
			}
			var parts []string
			complete := true
			for _, f := range c.fields {
				val, ok, multi := v.fieldValue(t, f)
				if multi {
					v.add(t, "%s %s: a field selects more than one value", kindName(c.kind), c.name)
					complete = false
					break
				}
				if !ok {
					if c.kind == idcKey {
						v.add(t, "key %s: a field selects no value", c.name)
					}
					complete = false
					break
				}
				if strings.HasPrefix(val, "?") {
					complete = false // a field node that was not assessed
					break
				}
				parts = append(parts, val)
			}
			if !complete {
				continue
			}
			key := strings.Join(parts, "\x00")
			switch c.kind {
			case idcKey, idcUnique:
				if tuples[key] {
					v.add(t, "%s %s: duplicate value %s", kindName(c.kind), c.name, display(parts))
				}
				tuples[key] = true
			case idcKeyref:
				if !v.inKeyTable(c.refer, info, key) {
					v.add(t, "keyref %s: no %s with value %s", c.name, sc.idcs[c.refer].name, display(parts))
				}
			}
		}
		if c.kind != idcKeyref {
			v.tables[ci] = append(v.tables[ci], keyTable{node: n, pre: info.pre, tuple: tuples})
		}
	}
}

func display(parts []string) string {
	out := make([]string, len(parts))
	for i, p := range parts {
		out[i] = strconv.Quote(p[1:])
	}
	return strings.Join(out, ", ")
}

func kindName(k uint8) string {
	return [...]string{"key", "unique", "keyref"}[k]
}

// inKeyTable looks a keyref's tuple up in the tables of the referenced
// key on the keyref's element and its descendants.
func (v *validator) inKeyTable(refer int32, at *nodeInfo, key string) bool {
	for _, t := range v.tables[refer] {
		if t.pre >= at.pre && t.pre < at.end && t.tuple[key] {
			return true
		}
	}
	return false
}

// sortedVersions returns the schema versions, oldest first.
func sortedVersions(sc *schemaTables) []string {
	out := make([]string, len(sc.versions))
	for i := range sc.versions {
		out[i] = sc.versions[i].version
	}
	sort.Slice(out, func(i, j int) bool { return versionNumber(out[i]) < versionNumber(out[j]) })
	return out
}

// versionNumber orders versions: 2.4 is 2.40, after 2.35.
func versionNumber(v string) int {
	major, minor, _ := strings.Cut(v, ".")
	for len(minor) < 2 {
		minor += "0"
	}
	a, _ := strconv.Atoi(major)
	b, _ := strconv.Atoi(minor[:2])
	return a*100 + b
}
